// MarshalText implements encoding.TextMarshaler.
func (s PriorityEnum) MarshalText() ([]byte, error) {
	switch s {
	case PriorityEnumUrgent:
		return []byte(s), nil
	case PriorityEnumHigh:
		return []byte(s), nil
	case PriorityEnumMedium:
		return []byte(s), nil
	case PriorityEnumLow:
		return []byte(s), nil
	case PriorityEnumNone:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

